// #95ffe2 API נתוני מגמות ודשבורד — аккаунт noa (цель lose_weight, главная метрика kcal). Только чтение.
import { test, expect, BrowserContext, Page } from '@playwright/test';
import { openAs, saveSession, getTrends, getGoal, ok, rest, pageUid, todayIn, uidFromAuthFile, expectInvariants, rangeCases, badRangeCases } from './_trends';

test.describe.configure({ mode: 'serial' });
// Встроенный Chromium Playwright на этой машине не запускается (context.md) — установленный Google Chrome.
test.use({ channel: 'chrome' });

test.describe('trends API — noa (kcal)', () => {
  let ctx: BrowserContext;
  let page: Page;
  let today: string;

  test.beforeAll(async ({ browser }) => {
    ({ ctx, page } = await openAs(browser, 'noa'));
    today = await todayIn(page);
  });
  test.afterAll(async () => {
    if (ctx) await saveSession(ctx, page, 'noa');
  });

  test('диапазоны day/week/month/year/custom — верные from/to/days и инварианты ответа #95ffe2 @desktop @prod-safe', async () => {
    // AC1: вход — диапазон day/week/month/year/custom; AC3/AC5/AC6/AC7 — инварианты каждого ответа.
    for (const c of rangeCases(today)) {
      const t = ok(await getTrends(page, c.range), c.name);
      expect(t.range, `${c.name}: range`).toMatchObject({ kind: c.range.kind, from: c.from, to: c.to, days: c.days });
      expectInvariants(t, `noa/${c.name}`);
    }
  });

  test('метрики по цели профиля: kcal первой, target = цель профиля, home ≤ 2 с главной первой #95ffe2 @desktop @prod-safe', async () => {
    // AC2 (метрики по профилю), AC3 (значение, личная цель, статус), AC4 (≤ 2 для главной).
    const { goal, keyMetrics } = await getGoal(page);
    expect(goal, 'у noa есть цель').not.toBeNull();
    expect(goal.primary, 'главная метрика noa — kcal').toBe('kcal');
    // Последний день с данными (сам день не зависит от того, есть ли еда сегодня).
    const last = await rest(page, 'GET', `rest/v1/daily_totals?select=local_date&local_date=lte.${today}&order=local_date.desc&limit=1`);
    expect(last.status).toBe(200);
    expect(last.body.length, 'предусловие: у noa есть хотя бы один день с едой в daily_totals').toBe(1);
    const date = last.body[0].local_date as string;

    const t = ok(await getTrends(page, { kind: 'day', date }), `day ${date}`);
    expectInvariants(t, `noa/day ${date}`);
    expect(t.enoughData, 'день с данными → enoughData').toBe(true);
    const expectedKeys = keyMetrics.filter((k) => Number(goal.targets?.[k]) > 0);
    expect(t.metrics.map((m) => m.key), 'метрики = ключевые метрики профиля с целью').toEqual(expectedKeys);
    expect(t.metrics[0].key, 'первая — kcal').toBe('kcal');
    for (const m of t.metrics) expect(m.target, `target ${m.key} = цель профиля`).toBe(goal.targets[m.key]);
    expect(t.home.length, 'home: 1–2 метрики').toBeGreaterThanOrEqual(1);
    expect(t.home.length).toBeLessThanOrEqual(2);
    expect(t.home[0].key, 'home[0] — главная kcal').toBe('kcal');
  });

  test('неверный диапазон → ошибка «invalid value: …» #95ffe2 @desktop @prod-safe', async () => {
    // AC9: ошибка при неверном диапазоне дат.
    for (const c of badRangeCases(today)) {
      const r = await getTrends(page, c.range);
      expect('error' in r ? r.error : `нет ошибки, ответ range=${JSON.stringify((r as any).range)}`, c.name).toBe(c.error);
    }
  });

  test('daily_totals отдаёт только строки самого пользователя (не morning) #95ffe2 @desktop @prod-safe', async () => {
    // AC8: данные только этого пользователя (view daily_totals, RLS security_invoker).
    const uid = await pageUid(page);
    const otherUid = uidFromAuthFile('morning');
    expect(otherUid).not.toBe(uid);
    const r = await rest(page, 'GET', 'rest/v1/daily_totals?select=user_id,local_date&limit=1000');
    expect(r.status).toBe(200);
    const rows = r.body as { user_id: string; local_date: string }[];
    expect(rows.length, 'предусловие: у noa есть строки').toBeGreaterThan(0);
    expect([...new Set(rows.map((x) => x.user_id))], 'все строки — свои').toEqual([uid]);
    expect(rows.map((x) => x.user_id), 'нет строк morning').not.toContain(otherUid);
    const dates = rows.map((x) => x.local_date);
    expect(new Set(dates).size, 'одна строка на дату (нет строк других пользователей)').toBe(dates.length);
    // Прямой запрос чужих строк фильтром — пусто.
    const foreign = await rest(page, 'GET', `rest/v1/daily_totals?select=user_id&user_id=eq.${otherUid}`);
    expect(foreign.status).toBe(200);
    expect(foreign.body, 'фильтр по чужому user_id → []').toEqual([]);
  });
});
